// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AISession) predicate.AISession {
	return predicate.AISession(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AISession) predicate.AISession {
	return predicate.AISession(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AISession) predicate.AISession {
	return predicate.AISession(sql.NotPredicates(p))
}
